import json
from collections import defaultdict

data = json.loads(open('graphify-out/graph.json', encoding='utf-8').read())
nodes = {n['id']: n for n in data['nodes']}

# candidate function/method nodes under internal/
func_nodes = {nid for nid,n in nodes.items() if n.get('source_file','').startswith('internal/') and n.get('label','').strip().endswith('()')}
print('num internal func/method nodes:', len(func_nodes))

call_rel = {'calls','indirect_call','method'}
in_edges = defaultdict(set)
for l in data['links']:
    if l['relation'] in ('calls','indirect_call'):
        src, tgt = l['source'], l['target']
        if tgt in func_nodes:
            in_edges[tgt].add(src)

ranked = sorted(in_edges.items(), key=lambda kv: -len(kv[1]))
for nid, callers in ranked[:15]:
    n = nodes[nid]
    print(len(callers), nid, n.get('label'), n.get('source_file'))
"
